#include <bits/stdc++.h>
using namespace std;

using LL = long long;
constexpr LL LIMIT = 1000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (cin >> s) {
        int n = static_cast<int>(s.size());

        if (n < 3 || n > 21) {
            cout << -1 << '\n';
            continue;
        }

        auto parse = [&](int l, int r, LL& value) {
            if (r - l > 1 && s[l] == '0') return false;

            value = 0;
            for (int i = l; i < r; ++i) {
                int digit = s[i] - '0';
                if (value > (LIMIT - digit) / 10) return false;
                value = value * 10 + digit;
            }
            return true;
        };

        LL answer = -1;

        for (int i = 1; i <= n - 2; ++i) {
            for (int j = i + 1; j <= n - 1; ++j) {
                LL a, b, c;
                if (!parse(0, i, a)) continue;
                if (!parse(i, j, b)) continue;
                if (!parse(j, n, c)) continue;
                answer = max(answer, a + b + c);
            }
        }

        cout << answer << '\n';
    }

    return 0;
}

