                LL a = 0, b = 0, c = 0;
                bool valid = true;

                for (int k = 0; k <= i; ++k) {
                    a = a * 10 + (s[k] - '0');
                    if (a > LIMIT) {
                        valid = false;
                        break;
                    }
                }

                if (valid) {
                    for (int k = i + 1; k <= j; ++k) {
                        b = b * 10 + (s[k] - '0');
                        if (b > LIMIT) {
                            valid = false;
                            break;
                        }
                    }
                }

                if (valid) {
                    for (int k = j + 1; k < n; ++k) {
                        c = c * 10 + (s[k] - '0');
                        if (c > LIMIT) {
                            valid = false;
                            break;
                        }
                    }
                }

                if (valid) {
                    ans = max(ans, a + b + c);
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

